mapper.select:
select p.id as paymentId, p.order_id as orderId, method_code.code as paymentMethodCode, payStatus_code.code as paymentStatus from payment p
join common_code method_code on method_code.id = p.method_id join common_code payStatus_code on payStatus_code.id = p.status_id
where p.idempotency_key = #{idempotencyKey}

select method_code.id as methodId, method_config.active as enable
from common_code method_code join code_group method_group on method_code.code_grp_id = method_group.id join pay_method_cfg method_config on method_code.id = method_config.method_id
where method_group.group_code = 'PAYMENT_METHOD' and method_code.code = #{paymentMethodCode}
